package com.example.yuejie;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.util.*;import java.io.*;import org.json.*;
/** Real reader gesture/scroller boundary, isolated from library and network state. */
public final class TimingTouchChecks extends Instrumentation {
 ReaderSurface surface;ReaderPaginator layout;int centers,paragraphs;final JSONArray checks=new JSONArray();
 public void onCreate(Bundle args){start();}
 void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 void event(int action,float x){long t=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(t,t,action,x,800,0);surface.dispatchTouchEvent(e);e.recycle();}
 void setup(PageTurnMode mode){if(surface!=null)release();ReaderSettings settings=new ReaderSettings(getTargetContext());settings.comments=false;settings.pageTurnMode=mode;settings.font=20;
 StringBuilder text=new StringBuilder();for(int i=0;i<200;i++)text.append("翻页结束时点击仍然应当响应，正文位置连续。\n\n");
 layout=new ReaderPaginator(text.toString(),"点击时序检查",1080,1920,3,3,settings);
 ReaderSurface.Host host=new ReaderSurface.Host(){public ReaderSurface.Frame adjacent(int direction){int next=surface.frame.pageIndex+direction;return next<0||next>=layout.pages.size()?null:new ReaderSurface.Frame("fixture","点击时序检查",0,1,layout,next);}public void commit(ReaderSurface.Frame f){surface.setFrame(f);}public void needChapter(int dir){}public void center(){centers++;}public void sized(int w,int h){}public int battery(){return 80;}public Map<Integer,Long> commentCounts(String chapter){return Collections.emptyMap();}public void paragraph(int start){paragraphs++;}};
 surface=new ReaderSurface(getTargetContext(),settings,host);surface.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY));surface.layout(0,0,1080,1920);surface.setFrame(new ReaderSurface.Frame("fixture","点击时序检查",0,1,layout,2));centers=paragraphs=0;
 }
 void release(){surface.suspendRendering();surface.removeCallbacks(surface.warmer);}
 void finishAnimation(){long end=SystemClock.uptimeMillis()+2500;while(surface.animating()&&SystemClock.uptimeMillis()<end){SystemClock.sleep(16);surface.computeScroll();}require(!surface.animating(),"animation completes within deadline");}
 void extras(PageTurnMode mode)throws Exception{final Throwable[] error={null};runOnMainSync(()->{try{setup(mode);surface.turn(1);if(mode!=PageTurnMode.NONE)surface.animateTo(0,false);event(MotionEvent.ACTION_DOWN,970);event(MotionEvent.ACTION_UP,970);finishAnimation();require(surface.frame.pageIndex==(mode==PageTurnMode.NONE?4:3),"rollback interrupted by new tap");checks.put(new JSONObject().put("mode",mode.key).put("rollback_then_tap",true));
 setup(mode);surface.turn(1);event(MotionEvent.ACTION_DOWN,540);event(MotionEvent.ACTION_UP,540);require(centers==1&&surface.frame.pageIndex==3,"center tap at animation boundary opens menu once");checks.put(new JSONObject().put("mode",mode.key).put("center_once",true));
 setup(mode);surface.turn(1);event(MotionEvent.ACTION_DOWN,970);event(MotionEvent.ACTION_CANCEL,970);finishAnimation();require(surface.frame.pageIndex==3&&surface.commits==1,"cancelled second touch does not turn again");checks.put(new JSONObject().put("mode",mode.key).put("cancel_no_extra_turn",true));
 }catch(Throwable e){error[0]=e;}finally{release();}});if(error[0]!=null)throw new AssertionError(error[0]);}
 void osEvent(int action,float x,long down){MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,800,0);e.setSource(InputDevice.SOURCE_TOUCHSCREEN);require(getUiAutomation().injectInputEvent(e,true),"OS input injection");e.recycle();}
 String readingState()throws Exception{LocalLibrary library=new LocalLibrary(getTargetContext());JSONArray state=new JSONArray();for(String query:new String[]{"SELECT id,added,last_read FROM books ORDER BY id","SELECT * FROM progress ORDER BY book","SELECT * FROM bookmarks ORDER BY book,chapter,offset"}){try(android.database.Cursor c=library.getReadableDatabase().rawQuery(query,null)){while(c.moveToNext()){JSONArray row=new JSONArray();for(int i=0;i<c.getColumnCount();i++)row.put(c.isNull(i)?JSONObject.NULL:c.getString(i));state.put(row);}}}library.close();return state.toString();}
 void liveWindow()throws Exception{ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -n com.example.yuejie/.MainActivity");InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){while(in.read()!=-1){}}Activity activity=monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);require(activity!=null,"test window launched from shell");try{for(PageTurnMode mode:PageTurnMode.values())for(int dir:new int[]{1,-1}){
 runOnMainSync(()->{setup(mode);activity.setContentView(surface);});SystemClock.sleep(200);
 runOnMainSync(()->surface.turn(1));int duration=mode==PageTurnMode.NONE?0:surface.scroller.getDuration();SystemClock.sleep(Math.max(0,duration-25));long down=SystemClock.uptimeMillis();float x=dir>0?970:100;osEvent(MotionEvent.ACTION_DOWN,x,down);SystemClock.sleep(45);osEvent(MotionEvent.ACTION_UP,x,down);
 long deadline=SystemClock.uptimeMillis()+2200;final boolean[] ended={false};while(SystemClock.uptimeMillis()<deadline){runOnMainSync(()->ended[0]=!surface.animating());if(ended[0])break;SystemClock.sleep(20);}final int[] actual={-1};runOnMainSync(()->{actual[0]=surface.frame.pageIndex;release();});require(actual[0]==3+dir,"live OS boundary click "+mode.key+" direction="+dir+" actual="+actual[0]);checks.put(new JSONObject().put("mode",mode.key).put("live_os_direction",dir).put("accepted",true));Bundle status=new Bundle();status.putString("stream","PASS OS "+mode.key+" direction="+dir+"\n");sendStatus(0,status);
 }}finally{runOnMainSync(activity::finish);}}
 void boundary(PageTurnMode mode,boolean expired,int tapDirection)throws Exception{
 final Throwable[] error={null};runOnMainSync(()->{try{setup(mode);surface.turn(1);require(surface.animating(),"fixture starts animation");int duration=surface.scroller.getDuration();
 // DOWN and UP straddle the final draw, just as a real input can precede a queued traversal.
 if(expired)SystemClock.sleep(duration+5);else SystemClock.sleep(Math.max(0,duration-25));
 event(MotionEvent.ACTION_DOWN,tapDirection>0?970:100);SystemClock.sleep(40);surface.computeScroll();event(MotionEvent.ACTION_UP,tapDirection>0?970:100);
 while(surface.animating()){SystemClock.sleep(16);surface.computeScroll();}
 int wanted=3+tapDirection;require(surface.frame.pageIndex==wanted,"end-of-animation tap dropped: mode="+mode.key+" expired="+expired+" wanted="+wanted+" actual="+surface.frame.pageIndex+" commits="+surface.commits);
 checks.put(new JSONObject().put("mode",mode.key).put("expired_before_down",expired).put("tap_direction",tapDirection).put("page",surface.frame.pageIndex));
 }catch(Throwable e){error[0]=e;}finally{if(surface!=null)release();}});if(error[0]!=null)throw new AssertionError(error[0]);}
 public void onStart(){Bundle result=new Bundle();Throwable failure=null;try{String before=readingState();for(PageTurnMode mode:new PageTurnMode[]{PageTurnMode.SIMULATION,PageTurnMode.COVER,PageTurnMode.SLIDE})for(boolean expired:new boolean[]{true,false})for(int dir:new int[]{1,-1})boundary(mode,expired,dir);for(PageTurnMode mode:PageTurnMode.values())extras(mode);Bundle progress=new Bundle();progress.putString("stream","PASS 24 isolated boundary and interruption checks; starting OS window checks\n");sendStatus(0,progress);liveWindow();require(before.equals(readingState()),"books, positions and bookmarks unchanged");checks.put(new JSONObject().put("user_reading_state_preserved",true));result.putString("stream","PASS "+checks.length()+" animation boundary checks\n");}catch(Throwable e){failure=e;result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));}try{File out=new File(getTargetContext().getFilesDir(),"touch-timing");out.mkdirs();try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(out,"results.json")),"UTF-8")){w.write(new JSONObject().put("success",failure==null).put("checks",checks).put("failure",failure==null?JSONObject.NULL:android.util.Log.getStackTraceString(failure)).toString(2));}}catch(Exception e){result.putString("stream",e.toString());}finish(failure==null?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
